358		if _, err := s.EncounterRecords(doc, other.ID, eid); !errors.Is(err, ErrMismatchedPatient) {
359			t.Fatalf("cross-patient encounter err = %v", err)
360		}
361		if _, err := s.EncounterRecords(rcv, pid, eid); !errors.Is(err, ErrAccessDenied) {
362			t.Fatalf("receiver err = %v", err)
363		}
364	
365		// 患者不存在的错误。
366		if _, err := s.GetPatient(doc, "pat_missing"); !errors.Is(err, ErrNotFound) {
367			t.Fatalf("get missing err = %v", err)
368		}
369	}
